def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    width = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}
    transitions = [[-1] * width]
    failure = [0]
    terminal = [False]

    for pattern in banned:
        state = 0
        for ch in pattern:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                terminal.append(False)
            state = transitions[state][c]
        terminal[state] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for c in range(width):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[failure[state]][c]
            else:
                failure[child] = transitions[failure[state]][c]
                queue.append(child)

    safe = [state for state in range(len(transitions)) if not terminal[state]]
    index = {state: i for i, state in enumerate(safe)}
    size = len(safe)
    matrix = [[0] * size for _ in range(size)]

    for state in safe:
        row = matrix[index[state]]
        for destination in transitions[state]:
            if not terminal[destination]:
                row[index[destination]] += 1

    def square(a):
        result = [[0] * size for _ in range(size)]
        for i, row in enumerate(a):
            out = result[i]
            for k, coefficient in enumerate(row):
                if coefficient:
                    for j, value in enumerate(a[k]):
                        out[j] += coefficient * value
            for j in range(size):
                out[j] %= MOD
        return result

    counts = [0] * size
    counts[index[0]] = 1

    while n:
        if n & 1:
            updated = [0] * size
            for i, count in enumerate(counts):
                if count:
                    for j, value in enumerate(matrix[i]):
                        updated[j] += count * value
            counts = [value % MOD for value in updated]

        n >>= 1
        if n:
            matrix = square(matrix)

    return sum(counts) % MOD
